//! # LDPC toolbox
//!
//! `ldpc_toolbox` is a collection of Rust utilities to generate LDPC codes.
//! The goal is to eventually support several LDPC design algorithms from the
//! literature.

#![warn(missing_docs)]
#![warn(unused)]

use crate::codes::nr5g::BaseGraph::{BG1, BG2};
use crate::codes::nr5g::LiftingSize;
use crate::decoder::factory::DecoderFactory;
use crate::decoder::factory::DecoderImplementation::HLMinstarapproxf32;
use crate::decoder::DecoderOutput;
use std::iter::repeat_n;

pub mod codes;
pub mod decoder;
pub mod gf2;
pub mod sparse;
pub mod systematic;

mod linalg;

/// Decode a 5G LDPC payload
pub fn decode_ldpc(base_graph: usize, z_c: usize, data: &[f32]) -> Result<DecoderOutput, &'static str> {
    let h = match base_graph {
        1 => BG1,
        2 => BG2,
        _ => return Err("Unsupported base graph"),
    }.h(match z_c {
        2 => LiftingSize::Z2,
        3 => LiftingSize::Z3,
        4 => LiftingSize::Z4,
        5 => LiftingSize::Z5,
        6 => LiftingSize::Z6,
        7 => LiftingSize::Z7,
        8 => LiftingSize::Z8,
        9 => LiftingSize::Z9,
        10 => LiftingSize::Z10,
        11 => LiftingSize::Z11,
        12 => LiftingSize::Z12,
        13 => LiftingSize::Z13,
        14 => LiftingSize::Z14,
        15 => LiftingSize::Z15,
        16 => LiftingSize::Z16,
        18 => LiftingSize::Z18,
        20 => LiftingSize::Z20,
        22 => LiftingSize::Z22,
        24 => LiftingSize::Z24,
        26 => LiftingSize::Z26,
        28 => LiftingSize::Z28,
        30 => LiftingSize::Z30,
        32 => LiftingSize::Z32,
        36 => LiftingSize::Z36,
        40 => LiftingSize::Z40,
        44 => LiftingSize::Z44,
        48 => LiftingSize::Z48,
        52 => LiftingSize::Z52,
        56 => LiftingSize::Z56,
        60 => LiftingSize::Z60,
        64 => LiftingSize::Z64,
        72 => LiftingSize::Z72,
        80 => LiftingSize::Z80,
        88 => LiftingSize::Z88,
        96 => LiftingSize::Z96,
        104 => LiftingSize::Z104,
        112 => LiftingSize::Z112,
        120 => LiftingSize::Z120,
        128 => LiftingSize::Z128,
        144 => LiftingSize::Z144,
        160 => LiftingSize::Z160,
        176 => LiftingSize::Z176,
        192 => LiftingSize::Z192,
        208 => LiftingSize::Z208,
        224 => LiftingSize::Z224,
        240 => LiftingSize::Z240,
        256 => LiftingSize::Z256,
        288 => LiftingSize::Z288,
        320 => LiftingSize::Z320,
        352 => LiftingSize::Z352,
        384 => LiftingSize::Z384,
        _ => return Err("Incorrect lifting size specified")
    });
    let mut dec = HLMinstarapproxf32.build_decoder(h);
    let data_f64 = repeat_n(&0f32, 2 * z_c).chain(data.iter()).map(|x| *x as f64).collect::<Vec<_>>();
    dec.decode(&data_f64, 12).map_err(|_| "Decoding failed")
}

